"""Mahāvagga — The Great Book (SN 45-56). One discourse per page, with
merged pages for peyyāla (formula-repetition) ranges wherever
bilara-data itself stores them as a single file."""

SC = "https://suttacentral.net"

INDEX_HEADING = "V. Mahāvagga — The Great Book"
