# within this book's own range (SN 45-56): SN 45.8 (Vibhaṅgasutta,
# "Analysis"), SN 55.1 (Cakkavattirājasutta, "A Wheel-Turning
# Monarch"), SN 56.11 (Dhammacakkappavattanasutta, "Rolling Forth the
# Wheel of Dhamma"), and SN 56.31 (Siṁsapāsutta, "In a Rosewood
# Forest") -- confirmed by listing every already-published sn-4[5-9]
# and sn-5[0-6] file directly rather than assumed from Book IV's own
# four-page count. SN 56.31 is this book's own final page: its
# already-built "next" link points to "./" (the collection index),
# confirming it closes the entire original twenty-page curated
# selection -- no further pre-existing page exists anywhere beyond it.
# Registered here in INDEX_EXTRA and not generated by this module; SN
# 45.8 sits mid-vagga inside Avijjāvagga (SN 45.1-10, position 8 of
# 10) and will need the same "fragile junction" treatment Books
# II-IV's own already discovered (SN 12.15, SN 22.59, SN 35.28, SN
# 36.6, SN 41.1, SN 42.8, and others): once Avijjāvagga is generated,
# sn_build.py's auto-chain will skip straight over SN 45.8's own
# pre-existing page, and its neighbours' prev/next must be hand-patched
# after every single build of this module from that point on.
#
# Systematic coverage of this book starts at SN 45.1, the first
# discourse of Avijjāvagga, this saṃyutta's own first vagga. HEAD is
# the nearest already-published page immediately before this module's
# first new page -- SN 44.11, this project's own closing discourse of
# Book IV (Saḷāyatanavagga), whose own "next" link (a static field
# baked into its already-built HTML file) still points to SN 45.8, the
# old placeholder hand-off target from before this module began. SN
# 44.11's own next must be hand-edited once, right now, to point to SN
# 45.1 -- the same one-time fix every earlier book's own HEAD page
# received when that book began.
#
# TAIL points at the nearest already-published page beyond whatever
# this module currently covers -- moved forward as later vaggas are
# completed, exactly as every earlier book's own TAIL was moved across
# its own course. It started at SN 45.8, the nearest already-published
# page beyond nothing yet generated; now that Avijjāvagga (SN 45.1-10,
# including SN 45.8 itself, mid-vagga) is fully generated, SN 45.8 is
# absorbed into this module's own PAGES sequence (hand-patched, not
# auto-chained -- see the fragile-junction note above) and TAIL moves
# to SN 55.1, the next already-published page beyond this module's own
# current coverage -- there being no pre-existing page anywhere within
# SN 45.11-54's own range, confirmed by the directory listing above.
